package vn.vinhkhang.thuchi;
import org.springframework.web.bind.annotation.*;import jakarta.servlet.http.HttpServletRequest;import java.util.*;import java.nio.file.*;import java.time.*;
@RestController @RequestMapping("/api") public class SupplierLedger {
 final Api api;public SupplierLedger(Api api){this.api=api;}
 @ExceptionHandler(Api.Fail.class) org.springframework.http.ResponseEntity<?> fail(Api.Fail f){return api.fail(f);}
 @ExceptionHandler(Exception.class) org.springframework.http.ResponseEntity<?> other(Exception e){return api.other(e);}
 static long balance(Api a,long contact,long exclude){long original=a.db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM obligations WHERE deleted=0 AND kind='PAYABLE' AND debt_group='SUPPLIER' AND contact_id=?",Long.class,contact);long linked=a.db.queryForObject("SELECT COALESCE(SUM(v.amount),0) FROM vouchers v JOIN obligations o ON o.id=v.obligation_id WHERE v.deleted=0 AND o.deleted=0 AND o.kind='PAYABLE' AND o.debt_group='SUPPLIER' AND o.contact_id=? AND v.type='EXPENSE' AND v.id<>?",Long.class,contact,exclude);long payments=a.db.queryForObject("SELECT COALESCE(SUM(CASE WHEN purpose='SUPPLIER_PAYMENT' THEN amount ELSE -amount END),0) FROM vouchers WHERE deleted=0 AND contact_id=? AND purpose IN ('SUPPLIER_PAYMENT','SUPPLIER_REFUND') AND id<>?",Long.class,contact,exclude);long returned=a.db.queryForObject("SELECT COALESCE(SUM(amount),0) FROM supplier_adjustments WHERE deleted=0 AND contact_id=?",Long.class,contact);return original-linked-payments-returned;}
 static void supplier(Api a,long id){a.available("contacts",id);var c=a.one("contacts",id);if(!List.of("SUPPLIER","OTHER").contains(Api.str(c,"kind"))||Api.str(c,"party_type").equals("INVESTOR"))throw new Api.Fail(400,"Chọn nhà cung cấp");}
 @GetMapping("/supplier-ledger") public List<Map<String,Object>> suppliers(HttpServletRequest r){api.auth(r,false);var contacts=api.db.queryForList("SELECT c.* FROM contacts c WHERE c.deleted=0 AND ((c.kind IN ('SUPPLIER','OTHER') AND c.party_type='SUPPLIER') OR EXISTS(SELECT 1 FROM obligations o WHERE o.contact_id=c.id AND o.deleted=0 AND o.kind='PAYABLE' AND o.debt_group='SUPPLIER')) ORDER BY c.name COLLATE NOCASE");for(var c:contacts){long id=Api.num(c,"id");var entries=events(id);c.put("balance",balance(api,id,0));c.put("total_import",entries.stream().mapToLong(e->Api.str(e,"kind").equals("IMPORT")?Api.num(e,"increase"):0).sum());c.put("total_paid",entries.stream().mapToLong(e->List.of("PAYMENT","LEGACY_PAYMENT").contains(Api.str(e,"kind"))?Api.num(e,"decrease"):0).sum());c.put("total_return",entries.stream().mapToLong(e->Api.str(e,"kind").equals("RETURN")?Api.num(e,"decrease"):0).sum());c.put("total_refund",entries.stream().mapToLong(e->Api.str(e,"kind").equals("REFUND")?Api.num(e,"increase"):0).sum());}return contacts;}
 long order(String table,long id){var rows=api.db.queryForList("SELECT MIN(id) n FROM audit WHERE entity=? AND entity_id=? AND action IN ('CREATE','VOID','UPDATE')",table,id);Object n=rows.getFirst().get("n");return n==null?id:((Number)n).longValue();}
 List<Map<String,Object>> events(long contact){var events=new ArrayList<Map<String,Object>>();for(var o:api.db.queryForList("SELECT * FROM obligations WHERE contact_id=? AND deleted=0 AND kind='PAYABLE' AND debt_group='SUPPLIER'",contact))events.add(event("IMPORT","obligations",o,Api.num(o,"amount"),0));for(var v:api.db.queryForList("SELECT v.* FROM vouchers v LEFT JOIN obligations o ON o.id=v.obligation_id WHERE v.deleted=0 AND ((v.contact_id=? AND v.purpose IN ('SUPPLIER_PAYMENT','SUPPLIER_REFUND')) OR (o.contact_id=? AND o.deleted=0 AND o.kind='PAYABLE' AND o.debt_group='SUPPLIER' AND v.type='EXPENSE'))",contact,contact)){boolean refund=Api.str(v,"purpose").equals("SUPPLIER_REFUND");events.add(event(refund?"REFUND":Api.str(v,"purpose").equals("SUPPLIER_PAYMENT")?"PAYMENT":"LEGACY_PAYMENT","vouchers",v,refund?Api.num(v,"amount"):0,refund?0:Api.num(v,"amount")));}for(var a:api.db.queryForList("SELECT * FROM supplier_adjustments WHERE contact_id=? AND deleted=0",contact))events.add(event("RETURN","supplier_adjustments",a,0,Api.num(a,"amount")));events.sort(Comparator.comparing((Map<String,Object>e)->Api.str(e,"date")).thenComparingLong(e->Api.num(e,"order")));long running=0;for(var e:events){running+=Api.num(e,"increase")-Api.num(e,"decrease");e.put("balance",running);}return events;}
 Map<String,Object> event(String kind,String entity,Map<String,Object>row,long increase,long decrease){var e=new LinkedHashMap<String,Object>();e.put("kind",kind);e.put("entity",entity);e.put("id",row.get("id"));e.put("date",row.get("date"));e.put("code",row.getOrDefault("code","TH-"+row.get("id")));e.put("description",row.get("description"));e.put("increase",increase);e.put("decrease",decrease);e.put("order",order(entity,Api.num(row,"id")));e.put("row",row);return e;}
 @GetMapping("/supplier-ledger/{id}") public Map<String,Object> detail(@PathVariable long id,HttpServletRequest r){api.auth(r,false);api.available("contacts",id);return Map.of("contact",api.one("contacts",id),"events",events(id),"balance",balance(api,id,0));}
 @GetMapping("/supplier-adjustments") public List<Map<String,Object>> adjustments(HttpServletRequest r){api.auth(r,false);return api.db.queryForList("SELECT * FROM supplier_adjustments WHERE deleted=0 ORDER BY date DESC,id DESC");}
 Map<String,Object> saveAdjustment(long id,Map<String,Object>b,long actor){long contact=Api.num(b,"contact_id"),amount=Api.num(b,"amount");supplier(api,contact);Api.amount(amount);String date=Api.date(b,"date"),description=Api.required(b,"description");var old=id==0?null:api.one("supplier_adjustments",id);if(old!=null){if(Api.num(old,"deleted")!=0||Api.num(old,"version")!=Api.num(b,"version"))throw new Api.Fail(409,"Phiếu trả hàng đã thay đổi");Api.required(b,"reason");if(Api.num(old,"contact_id")!=contact)throw new Api.Fail(400,"Không đổi nhà cung cấp của phiếu trả hàng");api.db.update("UPDATE supplier_adjustments SET date=?,description=?,amount=?,version=version+1 WHERE id=?",date,description,amount,id);}else{api.db.update("INSERT INTO supplier_adjustments(contact_id,date,description,amount,source_key) VALUES(?,?,?,?,?)",contact,date,description,amount,Api.str(b,"source_key").isEmpty()?null:Api.str(b,"source_key"));id=api.last();}api.audit(actor,old==null?"CREATE":"UPDATE","supplier_adjustments",id,old,api.one("supplier_adjustments",id),Api.str(b,"reason"));return api.one("supplier_adjustments",id);}
 @PostMapping("/supplier-adjustments") public Map<String,Object> create(@RequestBody Map<String,Object>b,HttpServletRequest r){long actor=api.actor(r);if(!Api.str(b,"source_key").isEmpty())throw new Api.Fail(400,"Mã nguồn chỉ dùng khi đồng bộ");return api.tx.execute(tx->saveAdjustment(0,b,actor));}
 @PutMapping("/supplier-adjustments/{id}") public Map<String,Object> edit(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){long actor=api.actor(r);return api.tx.execute(tx->saveAdjustment(id,b,actor));}
 @DeleteMapping("/supplier-adjustments/{id}") public Map<String,Object> delete(@PathVariable long id,@RequestBody Map<String,Object>b,HttpServletRequest r){long actor=api.actor(r);return api.tx.execute(tx->{var old=api.one("supplier_adjustments",id);if(Api.num(old,"deleted")!=0||Api.num(old,"version")!=Api.num(b,"version"))throw new Api.Fail(409,"Phiếu trả hàng đã thay đổi");String reason=Api.required(b,"reason");api.db.update("UPDATE supplier_adjustments SET deleted=1,version=version+1 WHERE id=?",id);api.audit(actor,"DELETE","supplier_adjustments",id,old,api.one("supplier_adjustments",id),reason);return Map.of("ok",true);});}
 String operation(Map<String,Object>d){return Api.str(d,"operation").isEmpty()?"IN":Api.str(d,"operation");}
 boolean same(Map<String,Object>a,Map<String,Object>b){for(String key:List.of("id","code","status","deleted","supplier_id","supplier_name","phone","address","date","note","priced","amount","items"))if(!Objects.equals(a.get(key),b.get(key)))return false;return operation(a).equals(operation(b));}
 @SuppressWarnings("unchecked") Map<String,Object> parse(String json){try{return api.json.readValue(json,Map.class);}catch(Exception e){throw new Api.Fail(400,"Dữ liệu nguồn kho không hợp lệ");}}
 long mapSupplier(String source,Map<String,Object>d,long actor){String id=Api.required(d,"supplier_id");var maps=api.db.queryForList("SELECT contact_id FROM warehouse_suppliers WHERE source_id=? AND supplier_id=?",source,id);if(!maps.isEmpty()){long contact=((Number)maps.getFirst().get("contact_id")).longValue();supplier(api,contact);return contact;}var matches=api.db.queryForList("SELECT id FROM contacts WHERE deleted=0 AND kind='SUPPLIER' AND party_type='SUPPLIER' AND name=? COLLATE NOCASE",Api.required(d,"supplier_name"));long contact=matches.size()==1?((Number)matches.getFirst().get("id")).longValue():Api.num(api.saveMaster("contacts",0,Map.of("kind","SUPPLIER","party_type","SUPPLIER","name",Api.required(d,"supplier_name"),"phone",Api.str(d,"phone"),"address",Api.str(d,"address"),"note","Từ kho · "+Api.str(d,"supplier_code")),actor),"id");api.db.update("INSERT INTO warehouse_suppliers VALUES(?,?,?)",source,id,contact);return contact;}
 boolean posted(Map<String,Object>d){return "POSTED".equals(d.get("status"))&&!Boolean.TRUE.equals(d.get("deleted"));}
 Map<String,Object> apply(Map<String,Object>link,Map<String,Object>d,long actor,boolean confirmed){String source=Api.str(link,"source_id"),doc=Api.str(link,"document_id");if(Api.str(link,"state").equals("PURGED"))return Map.of("ok",true);long adjustment=Api.num(link,"adjustment_id"),obligation=Api.num(link,"obligation_id");String reason="Đối chiếu phiếu kho · "+doc;if(!posted(d)){if(!confirmed)throw new Api.Fail(409,"Cần xác nhận hủy phiếu kho");if(adjustment>0){var old=api.one("supplier_adjustments",adjustment);api.db.update("UPDATE supplier_adjustments SET deleted=1,version=version+1 WHERE id=?",adjustment);api.audit(actor,"DELETE","supplier_adjustments",adjustment,old,api.one("supplier_adjustments",adjustment),reason);}if(obligation>0){if(api.db.queryForObject("SELECT COUNT(*) FROM vouchers WHERE deleted=0 AND obligation_id=?",Integer.class,obligation)>0)throw new Api.Fail(400,"Phiếu nhập có thanh toán liên kết cũ. Chuyển thanh toán sang tổng nhà cung cấp trước khi hủy.");var old=api.one("obligations",obligation);api.db.update("UPDATE obligations SET deleted=1,version=version+1 WHERE id=?",obligation);api.audit(actor,"DELETE","obligations",obligation,old,api.one("obligations",obligation),reason);}}
 else{if(!Boolean.TRUE.equals(d.get("priced")))throw new Api.Fail(400,"Phiếu kho chưa đủ đơn giá");long contact=mapSupplier(source,d,actor);if(adjustment>0){var old=api.one("supplier_adjustments",adjustment);if(Api.num(old,"deleted")!=0)throw new Api.Fail(400,"Phiếu trả hàng đã xóa ở Thu Chi; khôi phục trước khi đối chiếu");saveAdjustment(adjustment,Map.of("contact_id",contact,"date",Api.required(d,"date"),"amount",Api.num(d,"amount"),"description","Trả linh kiện từ kho · "+Api.required(d,"code"),"version",old.get("version"),"reason",reason),actor);}else if(obligation>0){var old=api.one("obligations",obligation);var body=new LinkedHashMap<>(old);body.put("amount",Api.num(d,"amount"));body.put("date",Api.required(d,"date"));body.put("contact_id",contact);body.put("description","Nhập linh kiện từ kho · "+Api.required(d,"code")+" · "+Api.str(d,"note"));body.put("reason",reason);api.saveObligation(obligation,body,actor);}}
 String text=api.serialize(d);api.db.update("UPDATE warehouse_links SET snapshot_json=?,pending_json='',state=? WHERE source_id=? AND document_id=?",text,posted(d)?"SYNCED":"CANCELLED_CONFIRMED",source,doc);return Map.of("ok",true);}
 @PostMapping("/warehouse/reconcile") public Map<String,Object> reconcile(@RequestBody Map<String,Object>b,HttpServletRequest r){long actor=api.actor(r);if(!Boolean.TRUE.equals(b.get("confirmed")))throw new Api.Fail(400,"Xác nhận cập nhật công nợ");return api.tx.execute(tx->{var rows=api.db.queryForList("SELECT * FROM warehouse_links WHERE source_id=? AND document_id=?",Api.required(b,"source"),Api.required(b,"document"));if(rows.isEmpty())throw new Api.Fail(404,"Không có phiếu đối chiếu");var link=rows.getFirst();if(Api.str(link,"pending_json").isEmpty())throw new Api.Fail(409,"Không có thay đổi đang chờ");if(!Api.str(link,"pending_json").equals(Api.required(b,"pending_json")))throw new Api.Fail(409,"Phiếu kho đã thay đổi. Đồng bộ và kiểm tra lại.");return apply(link,parse(Api.str(link,"pending_json")),actor,true);});}
 Map<String,Object> sync(Map<String,Object>b,HttpServletRequest r)throws Exception{long actor=api.actor(r);String source=Api.required(b,"source");var configs=api.db.queryForList("SELECT * FROM warehouse_sources WHERE id=?",source);if(configs.isEmpty())throw new Api.Fail(400,"Kết nối Kho trước");var snapshot=new Extensions(api).read(Path.of(Api.str(configs.getFirst(),"path")));if(!source.equals(snapshot.get("source_id")))throw new Api.Fail(409,"Nguồn kho thay đổi, kết nối lại");return api.tx.execute(tx->{int created=0,unchanged=0,issues=0,skipped=0,updated=0;var seen=new HashSet<String>();for(Object value:(List<?>)snapshot.get("documents")){@SuppressWarnings("unchecked") var d=(Map<String,Object>)value;String doc=Api.required(d,"id");if(!seen.add(doc))throw new Api.Fail(400,"Mã phiếu trùng");String text=api.serialize(d);var links=api.db.queryForList("SELECT * FROM warehouse_links WHERE source_id=? AND document_id=?",source,doc);
 if(!links.isEmpty()){var link=links.getFirst();String state=Api.str(link,"state");if(state.equals("PURGED")){unchanged++;continue;}var old=parse(Api.str(link,"snapshot_json"));if(same(old,d)){if(state.equals("CHANGED")||state.equals("CANCELLED")||state.equals("MISSING"))api.db.update("UPDATE warehouse_links SET state='SYNCED',pending_json='' WHERE source_id=? AND document_id=?",source,doc);unchanged++;continue;}long ob=Api.num(link,"obligation_id"),adj=Api.num(link,"adjustment_id");boolean unpaid=ob>0&&api.db.queryForObject("SELECT COUNT(*) FROM vouchers WHERE deleted=0 AND (obligation_id=? OR (contact_id=(SELECT contact_id FROM obligations WHERE id=?) AND purpose IN ('SUPPLIER_PAYMENT','SUPPLIER_REFUND')))",Integer.class,ob,ob)==0;boolean sameSupplier=Api.str(old,"supplier_id").equals(Api.str(d,"supplier_id"));if(unpaid&&sameSupplier&&posted(d)&&operation(d).equals("IN")&&Boolean.TRUE.equals(d.get("priced"))&&Api.num(d,"amount")>0&&Api.num(api.one("obligations",ob),"deleted")==0){apply(link,d,actor,false);updated++;}else{api.db.update("UPDATE warehouse_links SET pending_json=?,state=? WHERE source_id=? AND document_id=?",text,posted(d)?"CHANGED":"CANCELLED",source,doc);issues++;}continue;}
 if(!posted(d)||!Boolean.TRUE.equals(d.get("priced"))||Api.num(d,"amount")<=0||Api.str(d,"supplier_id").isEmpty()||Api.str(d,"supplier_name").isEmpty()){skipped++;continue;}long contact=mapSupplier(source,d,actor);if(operation(d).equals("RETURN")){var adj=saveAdjustment(0,Map.of("contact_id",contact,"date",Api.required(d,"date"),"amount",Api.num(d,"amount"),"description","Trả linh kiện từ kho · "+Api.required(d,"code"),"source_key",source+":"+doc),actor);api.db.update("INSERT INTO warehouse_links(source_id,document_id,supplier_id,snapshot_json,adjustment_id) VALUES(?,?,?,?,?)",source,doc,Api.str(d,"supplier_id"),text,adj.get("id"));}else if(operation(d).equals("IN")){var ob=api.saveObligation(0,Map.of("kind","PAYABLE","debt_group","SUPPLIER","contact_id",contact,"amount",Api.num(d,"amount"),"date",Api.required(d,"date"),"description","Nhập linh kiện từ kho · "+Api.required(d,"code")+" · "+Api.str(d,"note")),actor);api.db.update("INSERT INTO warehouse_links(source_id,document_id,obligation_id,supplier_id,snapshot_json) VALUES(?,?,?,?,?)",source,doc,ob.get("id"),Api.str(d,"supplier_id"),text);}else throw new Api.Fail(400,"Nghiệp vụ kho không hợp lệ");created++;}
 for(var link:api.db.queryForList("SELECT * FROM warehouse_links WHERE source_id=? AND state NOT IN ('PURGED','CANCELLED_CONFIRMED')",source))if(!seen.contains(Api.str(link,"document_id"))){var missing=parse(Api.str(link,"snapshot_json"));missing.put("deleted",true);api.db.update("UPDATE warehouse_links SET state='MISSING',pending_json=? WHERE source_id=? AND document_id=?",api.serialize(missing),source,link.get("document_id"));issues++;}api.db.update("UPDATE warehouse_sources SET last_sync=? WHERE id=?",Instant.now().toString(),source);Map<String,Object> result=Map.of("created",created,"unchanged",unchanged,"issues",issues,"skipped",skipped,"updated",updated,"generated_at",Api.str(snapshot,"generated_at"));api.audit(actor,"SYNC_WAREHOUSE","warehouse",0,null,result,"");return result;});}
}
